import{_ as a,a0 as p,w as s,s as e,I as u,x as n,a1 as o,A as l,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const V=JSON.parse('{"title":"完整指南：使用 VirtualBox 在 Windows 上安裝 Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"完整指南：使用 VirtualBox 在 Windows 上安裝 Ubuntu | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"完整指南：使用 VirtualBox 在 Windows 上安裝 Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"完整指南：使用 VirtualBox 在 Windows 上安裝 Ubuntu | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20230112.3 ⭐️⭐️ Install Ubuntu on Windows Using VirtualBox [Complete Guide]","title":"完整指南：使用 VirtualBox 在 Windows 上安裝 Ubuntu","tag":"202301","desc":""},"relativePath":"202301/20230112.3 ⭐️⭐️ Install Ubuntu on Windows Using VirtualBox [Complete Guide].md","filePath":"[post].md"}'),b={name:"202301/20230112.3 ⭐️⭐️ Install Ubuntu on Windows Using VirtualBox [Complete Guide].md"};function d(w,t,g,m,x,y){const r=p("Link");return s(),e("div",null,[t[29]||(t[29]=u("h1",{id:"完整指南-使用-virtualbox-在-windows-上安裝-ubuntu",tabindex:"-1"},[n("完整指南：使用 VirtualBox 在 Windows 上安裝 Ubuntu "),u("a",{class:"header-anchor",href:"#完整指南-使用-virtualbox-在-windows-上安裝-ubuntu","aria-label":"Permalink to “完整指南：使用 VirtualBox 在 Windows 上安裝 Ubuntu”"},"​")],-1)),t[30]||(t[30]=u("p",null,[u("img",{src:"https://img.linux.net.cn/data/attachment/album/202301/23/230204pr8c36xesq5r8vx9.jpg",alt:""})],-1)),t[31]||(t[31]=u("blockquote",null,[u("p",null,"本教程將指導你用最簡單的步驟在 Windows 上的 Oracle VirtualBox 上安裝 Ubuntu 桌面版。")],-1)),u("p",null,[o(r,{href:"https://www.debugpoint.com/tag/virtualbox"},{default:l(()=>[...t[0]||(t[0]=[n("VirtualBox",-1)])]),_:1}),t[1]||(t[1]=n(" 是 Oracle 的一款流行的虛擬化軟件，可用於 Linux、mac 和 Windows 系統。它是靈活的，並提供了許多功能來實現虛擬化。這是在 Windows 中體驗 Ubuntu 而不安裝它的最佳且簡單的方法。然而，我強烈建議將 Ubuntu 以雙引導的方式安裝在物理機上，從而更好地體驗 Ubuntu。",-1))]),t[32]||(t[32]=i('<p>下面列出的步驟假設你是第一次在 Windows 中安裝 Ubuntu。因此，這些步驟有點描述性，也有點冗長。此外，以下步驟適用於 Windows 10 和 Windows 11 作為宿主機。</p><h3 id="你需要什麼" tabindex="-1">你需要什麼 <a class="header-anchor" href="#你需要什麼" aria-label="Permalink to “你需要什麼”">​</a></h3><ul><li>可上網的 PC</li><li>用於安裝的 Ubuntu Linux ISO 鏡像文件</li><li>安裝了 VirtualBox 的 Windows 系統</li></ul><h3 id="使用-virtualbox-在-windows-上安裝-ubuntu" tabindex="-1">使用 VirtualBox 在 Windows 上安裝 Ubuntu <a class="header-anchor" href="#使用-virtualbox-在-windows-上安裝-ubuntu" aria-label="Permalink to “使用 VirtualBox 在 Windows 上安裝 Ubuntu”">​</a></h3><h4 id="下載並安裝必要的東西" tabindex="-1">下載並安裝必要的東西 <a class="header-anchor" href="#下載並安裝必要的東西" aria-label="Permalink to “下載並安裝必要的東西”">​</a></h4><p>從以下鏈接下載 Ubuntu Linux 桌面版 ISO 鏡像文件。</p>',6)),u("blockquote",null,[u("p",null,[u("strong",null,[o(r,{href:"https://ubuntu.com/download/desktop"},{default:l(()=>[...t[2]||(t[2]=[n("下載 Ubuntu 桌面版",-1)])]),_:1})])])]),t[33]||(t[33]=u("p",null,"此外，請從下面的官方網站下載 Oracle VirtualBox 安裝程序。",-1)),u("blockquote",null,[u("p",null,[u("strong",null,[o(r,{href:"https://www.virtualbox.org/wiki/Downloads"},{default:l(()=>[...t[3]||(t[3]=[n("下載 VirtualBox",-1)])]),_:1})])])]),t[34]||(t[34]=u("p",null,[u("img",{src:"https://www.debugpoint.com/wp-content/uploads/2023/01/Download-location-for-VirtualBox-for-Windows.jpg",alt:"VirtualBox for Windows 的下載位置"})],-1)),t[35]||(t[35]=u("h4",{id:"如何安裝和配置-virtualbox",tabindex:"-1"},[n("如何安裝和配置 VirtualBox "),u("a",{class:"header-anchor",href:"#如何安裝和配置-virtualbox","aria-label":"Permalink to “如何安裝和配置 VirtualBox”"},"​")],-1)),t[36]||(t[36]=u("p",null,"Windows 中的 VirtualBox 需要 “Microsoft Visual C++ 2019 Redistrobutiable package”。你必須先安裝它。從以下鏈接下載軟件包（X64 架構）：",-1)),u("blockquote",null,[u("p",null,[u("strong",null,[o(r,{href:"https://learn.microsoft.com/en-us/cpp/windows/latest-supported-vc-redist?view=msvc-170"},{default:l(()=>[...t[4]||(t[4]=[n("下載 MSVC",-1)])]),_:1})])])]),t[37]||(t[37]=u("p",null,[u("img",{src:"https://www.debugpoint.com/wp-content/uploads/2023/01/Download-the-dependency-for-VirtualBox.jpg",alt:"下載 VirtualBox 的依賴項"})],-1)),t[38]||(t[38]=u("p",null,[u("img",{src:"https://www.debugpoint.com/wp-content/uploads/2023/01/Install-the-dependency-for-VirtualBox.jpg",alt:"安裝 VirtualBox 的依賴項"})],-1)),t[39]||(t[39]=u("p",null,"完成以上安裝後，從以下鏈接下載最新的 Python 包。Python 綁定也是 Windows 端 VirtualBox 安裝所需的依賴項。",-1)),u("blockquote",null,[u("p",null,[u("strong",null,[o(r,{href:"https://www.python.org/downloads/windows/"},{default:l(()=>[...t[5]||(t[5]=[n("下載 Python for Windows",-1)])]),_:1})])])]),t[40]||(t[40]=i('<p>然後，啓動 VirtualBox 安裝程序並按照屏幕上的説明進行安裝。</p><p>安裝後，重新啓動 Windows 系統。</p><h4 id="為-ubuntu-設置虛擬機" tabindex="-1">為 Ubuntu 設置虛擬機 <a class="header-anchor" href="#為-ubuntu-設置虛擬機" aria-label="Permalink to “為 Ubuntu 設置虛擬機”">​</a></h4><p>從開始菜單啓動 VirtualBox。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-VirtualBox-from-start-menu.jpg" alt="從開始菜單中選擇 VirtualBox"></p><p>在 VirtualBox 窗口工具欄上，單擊 “<ruby>新建<rt>New</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Click-on-New.jpg" alt="單擊新建"></p>',7)),u("ul",null,[t[11]||(t[11]=u("li",null,"在創建虛擬機窗口中，輸入虛擬機的名稱。它可以是標識此版本 Ubuntu 的任何名稱。",-1)),t[12]||(t[12]=u("li",null,[n("保持 “"),u("ruby",null,[n("文件夾"),u("rt",null,"Folder")]),n("” 不變。這是創建虛擬機文件的路徑。")],-1)),t[13]||(t[13]=u("li",null,[n("在 “"),u("ruby",null,[n("ISO 鏡像文件"),u("rt",null,"ISO Image")]),n("” 一欄，瀏覽你下載的 Ubuntu ISO 文件。")],-1)),u("li",null,[t[7]||(t[7]=n("然後選擇 “",-1)),t[8]||(t[8]=u("ruby",null,[n("跳過無人值守安裝"),u("rt",null," Skip Unattended installation")],-1)),t[9]||(t[9]=n("”。如果不選擇此選項，將在虛擬機中創建一個 ",-1)),o(r,{href:"https://www.debugpoint.com/virtualbox-id-password/"},{default:l(()=>[...t[6]||(t[6]=[n("默認用户 id（vboxuser）和密碼",-1)])]),_:1}),t[10]||(t[10]=n("。讓我們暫時不要管它。",-1))])]),t[41]||(t[41]=i('<p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-the-ISO-file.jpg" alt="選擇 ISO 文件"></p><ul><li>單擊 “<ruby>硬件<rt>Hardware</rt></ruby>” 部分，並調整虛擬機所需的內存。一般的經驗是，虛擬機的內存大小應該小於主機系統中的物理內存。我建議對於 8 GB 內存系統的虛擬機使用 2 GB 到 4 GB。要選擇 4 GB 內存，拖動滑塊（或鍵入）使其為 4096 MB（即 4×1024）。</li><li>選擇 2 或 4 核處理器。</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-Hardware.jpg" alt="選擇硬件"></p><ul><li>單擊 “<ruby>硬盤<rt>Hard Disk</rt></ruby>” 部分，並保持文件位置不變。</li><li>為 Ubuntu 安裝提供至少 20 GB 到 25 GB 的容量。</li><li>硬盤文件類型值保持為 VDI（VirtualBox 磁盤鏡像）</li><li>不要選擇 “<ruby>預分配完整大小<rt>Pre-allocate Full Size</rt></ruby>”。</li><li>最後，單擊 “<ruby>完成<rt>Finish</rt></ruby>”。</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-Hard-Disk.jpg" alt="選擇硬盤"></p><p>你應該在 VirtualBox 的左側面板上看到一個新條目，其中包含一個 Ubuntu 22.04 條目（你之前設置的名稱）。</p><p>選擇條目並單擊 “<ruby>開始<rt>Start</rt></ruby>” 以引導到虛擬機：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Boot-Ubuntu-in-VirtualBox.jpg" alt="在 VirtualBox 中啓動 Ubuntu"></p><h4 id="使用-virtualbox-安裝-ubuntu" tabindex="-1">使用 VirtualBox 安裝 Ubuntu <a class="header-anchor" href="#使用-virtualbox-安裝-ubuntu" aria-label="Permalink to “使用 VirtualBox 安裝 Ubuntu”">​</a></h4><p>成功引導後，你應該看到以下屏幕，其中顯示了安裝 Ubuntu 的各種選項。選擇 “<ruby>嘗試 Ubuntu<rt>Try Ubuntu</rt></ruby>” 或 “<ruby>安裝 Ubuntu<rt>Install Ubuntu</rt></ruby>”。</p><p>在歡迎屏幕中，單擊 “<ruby>嘗試 Ubuntu<rt>Try Ubuntu</rt></ruby>”。過了一會兒，你會看到下面的 Ubuntu <ruby>臨場<rt>Live</rt></ruby>桌面。如果要更改分辨率，請右鍵單擊桌面並選擇顯示設置。並將分辨率更改為 1400×900。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/1-Select-Try-Ubuntu.jpg" alt="選擇嘗試 Ubuntu"></p><p>在桌面上，雙擊 “<ruby>安裝 Ubuntu<rt>Install Ubuntu</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/2-Ubuntu-LIVE-desktop-1.jpg" alt="Ubuntu LIVE 桌面"></p><p>在下一組屏幕中，根據需要選擇 “<ruby>語言<rt>Language</rt></ruby>” 和 “<ruby>鍵盤佈局<rt>Keyboard Layout</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-Language.jpg" alt="選擇語言"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/4-Select-Keybaord-Layout.jpg" alt="選擇鍵盤佈局"></p><p>安裝屏幕為你提供所需的安裝類型。選擇 “<ruby>正常安裝<rt>Normal Installation</rt></ruby>”，然後在 “<ruby>其他選項<rt>Other options</rt></ruby>” 下選擇兩個選項。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/5-Select-install-options.jpg" alt="選擇安裝選項"></p><p>由於你是在虛擬磁盤空間中安裝的，即它只是一個文件，因此你可以安全地選擇 “<ruby>擦除磁盤並安裝 Ubuntu<rt>Erase disk and install Ubuntu</rt></ruby>” 選項。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/6-Installation-Type.jpg" alt="安裝類型"></p><p>點擊 “<ruby>立即安裝<rt>Install Now</rt></ruby>” 並 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/7-Write-changes-to-disk.jpg" alt="將更改寫入磁盤"></p><p>然後選擇 “<ruby>地區<rt>region</rt></ruby>”，添加“<ruby>你的名字<rt>Your name</rt></ruby>”、“<ruby>計算機名稱<rt>Your computer&#39;s name</rt></ruby>”、“<ruby>用户名<rt>Username</rt></ruby>” 和 “<ruby>密碼<rt>Password</rt></ruby>”。這將是安裝後登錄 Ubuntu 的用户 id 和密碼。</p><p>單擊 “<ruby>繼續<rt>Continue</rt></ruby>” 開始安裝。等到它完成。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/8-User-account-creation.jpg" alt="創建用户帳户"></p><p>安裝完成後，單擊 “<ruby>立即重新啓動<rt>Restart Now</rt></ruby>”。等待幾秒鐘，你將看到一個登錄屏幕。使用用户 id 和密碼登錄。你應該看到 Ubuntu 桌面在 Windows 端 VirtualBox 中作為 VM 運行。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/10-Ubuntu-Installation-is-complete.jpg" alt="Ubuntu 安裝完成"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/11-Log-on-to-Ubuntu.jpg" alt="登錄 Ubuntu"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/12-Ubuntu-running-in-Windows-using-Virtualbox-2048x1280.jpg" alt="使用 Virtualbox 在 Windows 中運行的 Ubuntu"></p><h3 id="安裝後配置和提示-可選" tabindex="-1">安裝後配置和提示（可選） <a class="header-anchor" href="#安裝後配置和提示-可選" aria-label="Permalink to “安裝後配置和提示（可選）”">​</a></h3><h4 id="安裝客體機增強項" tabindex="-1">安裝客體機增強項 <a class="header-anchor" href="#安裝客體機增強項" aria-label="Permalink to “安裝客體機增強項”">​</a></h4><p>成功安裝後，應為 Windows 宿主機和 Ubuntu 客體機安裝 “<ruby>VirtualBox 客體機增強項<rt>VirtualBox guest additions</rt></ruby>”。客體機增強項是一組需要安裝在客體虛擬機（即 Ubuntu）內的軟件包，以啓用 <strong>共享文件夾、雙向複製 / 粘貼、自動更改分辨率</strong> 和許多類似功能。</p><p>要安裝它，請引導到 Ubuntu。從 VirtualBox 菜單中，選擇“<ruby>設備<rt>Devices</rt></ruby> &gt; <ruby>插入客體機增強 CD 鏡像<rt>Insert Guest Additions CD Image</rt></ruby>”。必要的軟件包將安裝在 Ubuntu 中。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-Guest-addition-from-the-menu.jpg" alt="從菜單中選擇客體機增強"></p><p>打開文件管理器並打開裝入的文件夾，如下所示。然後右鍵單擊 &gt; 選擇 “<ruby>在終端中打開<rt>open in terminal</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Open-the-mounted-disc-and-select-option-with-terminal.jpg" alt="打開已掛載的光盤並選擇帶有終端的選項"></p><p>然後運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ./VBoxLinuxAdditions.run</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/VirtualBox-guest-addition-install-for-Windows-host.jpg" alt="VirtualBox 為 Windows 主機添加客體機增強項"></p><p>完成上述命令後，重新啓動 Ubuntu VM。</p><h4 id="啓用-windows-和-ubuntu-之間的複製和粘貼" tabindex="-1">啓用 Windows 和 Ubuntu 之間的複製和粘貼 <a class="header-anchor" href="#啓用-windows-和-ubuntu-之間的複製和粘貼" aria-label="Permalink to “啓用 Windows 和 Ubuntu 之間的複製和粘貼”">​</a></h4><p>要在 Windows 和 Ubuntu 系統之間啓用複製和粘貼，請從菜單中選擇 “<ruby>設備<rt>Devices</rt></ruby> &gt; <ruby>共享剪貼板<rt>Shared Clipboard</rt></ruby> &gt; <ruby>雙向<rt>Bi-directional</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Enable-clipboard-sharing.jpg" alt="啓用共享剪貼板"></p><h4 id="關閉-ubuntu-vm" tabindex="-1">關閉 Ubuntu VM <a class="header-anchor" href="#關閉-ubuntu-vm" aria-label="Permalink to “關閉 Ubuntu VM”">​</a></h4><p>理想情況下，你應該從自己的關機菜單中關閉 VM。但是，你也可以從 VirtualBox 主窗口關閉。右鍵單擊虛擬機名稱並選擇 “<ruby>關閉<rt>Close</rt></ruby> &gt; <ruby>關機<rt>Poweroff</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Poweroff-Virtual-machine.jpg" alt="關閉虛擬機"></p><h4 id="如何刪除-ubuntu-並刪除所有數據" tabindex="-1">如何刪除 Ubuntu 並刪除所有數據 <a class="header-anchor" href="#如何刪除-ubuntu-並刪除所有數據" aria-label="Permalink to “如何刪除 Ubuntu 並刪除所有數據”">​</a></h4><p>如果要完全刪除虛擬機（例如 Ubuntu）及其數據，請選擇 “<ruby>刪除<rt>Remove</rt></ruby>” 和 “<ruby>刪除所有文件<rt>Delete All Files</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-remove-to-delete-a-VM.jpg" alt="選擇刪除以移除虛擬機"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Select-the-delete-options.jpg" alt="選擇刪除選項"></p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>在本教程中，你學習了使用 VirtualBox 在 Windows（10 或 11）上安裝 Ubuntu 的最簡單方法。此外，你還學習了幾步安裝後配置 Ubuntu VM 的基本步驟。你可以對 VirtualBox 中的其他任何 Linux 發行版使用上述步驟。</p><p>如果你有任何疑問，歡迎在下面發表評論。</p><hr>',55)),u("p",null,[t[15]||(t[15]=n("via: ",-1)),o(r,{href:"https://www.debugpoint.com/install-ubuntu-windows-virtualbox/"},{default:l(()=>[...t[14]||(t[14]=[n("https://www.debugpoint.com/install-ubuntu-windows-virtualbox/",-1)])]),_:1})]),u("p",null,[t[20]||(t[20]=n("作者：",-1)),o(r,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...t[16]||(t[16]=[n("Arindam",-1)])]),_:1}),t[21]||(t[21]=n(" 選題：",-1)),o(r,{href:"https://github.com/lkxed"},{default:l(()=>[...t[17]||(t[17]=[n("lkxed",-1)])]),_:1}),t[22]||(t[22]=n(" 譯者：",-1)),o(r,{href:"https://github.com/ZhangZhanhaoxiang"},{default:l(()=>[...t[18]||(t[18]=[n("ZhangZhanhaoxiang",-1)])]),_:1}),t[23]||(t[23]=n(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:l(()=>[...t[19]||(t[19]=[n("wxy",-1)])]),_:1})]),u("p",null,[t[26]||(t[26]=n("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[24]||(t[24]=[n("LCTT",-1)])]),_:1}),t[27]||(t[27]=n(" 原創編譯，",-1)),o(r,{href:"https://linux.cn/"},{default:l(()=>[...t[25]||(t[25]=[n("Linux中國",-1)])]),_:1}),t[28]||(t[28]=n(" 榮譽推出",-1))])])}const f=a(b,[["render",d]]);export{V as __pageData,f as default};
